    assert.equal(await evaluate('document.querySelector(".emoji-grid:last-child").querySelectorAll("[data-emoji]").length'),109);assert.equal(await evaluate('getComputedStyle(document.querySelector(".emoji-grid")).gridTemplateColumns.split(" ").length'),7);
