  await check('native auxiliary routes preserve hierarchy and show honest unavailable states',async()=>{
    await root('contacts');await click('[data-nav=role][data-arg="'+initialRole+'"]');await click('[data-action=contact-remark]');await fill('[name=tags]','QA_ROUTE');await click('.modal-submit');await wait('!document.querySelector(".contact-remark-editor")');await back();await click('[data-action=contact-tags]');await wait('document.querySelector("#view").dataset.route==="contact-tags"');await noAI('contact tags');await capture('390-contact-tags');await click('[data-nav=tag-contacts][data-arg=QA_ROUTE]');await wait('document.querySelector("#view").dataset.route==="tag-contacts"');assert.deepEqual(await evaluate('[...document.querySelectorAll("[data-nav=role]")].map(e=>e.dataset.arg)'),[initialRole]);await capture('390-tag-contacts');await back();assert.equal(await route(),'contact-tags');await back();assert.equal(await route(),'contacts');
    await click('[data-action=new-friends]');await wait('document.querySelector("#view").dataset.route==="new-friends"');await noAI('new friends');await capture('390-new-friends');assert.equal(await evaluate('!!document.querySelector(".topbar .new-friends-more")&&!document.querySelector(".topbar .new-friends-more").closest("button,[data-action]")'),true);await click('.new-friends-search');await wait('document.querySelector("#view").dataset.route==="add-friend"');await back();assert.equal(await route(),'new-friends');await back();assert.equal(await route(),'contacts');
    await root('me');await buttonText('表情');await wait('document.querySelector("#view").dataset.route==="sticker-store"');await noAI('sticker store');assert.match(await text(),/暂未开放/);await capture('390-sticker-store');await click('.topbar [data-action=manage-stickers]');await wait('document.querySelector("#view").dataset.route==="stickers"');await back();assert.equal(await route(),'sticker-store');await back();assert.equal(await route(),'me');
  });
  await check('background polling preserves a historical reading position',async()=>{
    await root('chats');await click('[data-open-chat="'+initialRole+'"]');if(!(await evaluate('(()=>{const l=document.querySelector("#chat-messages");return l.scrollHeight-l.clientHeight>200;})()'))){await fill('#compose-text','HISTORY_FIXTURE '.repeat(100));await click('#compose-form [type=submit]');await wait('Pipi.getState().messages.some(m=>m.content.startsWith("HISTORY_FIXTURE ")&&m.status==="error")');}assert.ok(await evaluate('(()=>{const l=document.querySelector("#chat-messages");return l.scrollHeight-l.clientHeight>200;})()'),'test history must be scrollable');await evaluate('new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)))');const listRect=await rect('#chat-messages');await command('Input.dispatchMouseEvent',{type:'mouseWheel',x:listRect.x+listRect.width/2,y:listRect.y+listRect.height/2,deltaX:0,deltaY:-100000});await wait('document.querySelector("#chat-messages").scrollTop<=3');await delay(150);assert.ok(await evaluate('document.querySelector("#chat-messages").scrollTop<=3'),'historical position is stable before mutation');await key('Escape');const revision=await evaluate('Pipi.getState().revision');await evaluate('Pipi.api("/api/action",{type:"profile.save",payload:{bio:"HEADLESS_POLL_REVISION"}})');await wait('Pipi.getState().revision>'+revision,10000);assert.ok(await evaluate('document.querySelector("#chat-messages").scrollTop<=3'),'polling must not jump to bottom');await capture('390-history-poll-position');
  });
  await check('all viewport roots and deep native pages stay within screen',async()=>{
    for(const [width,height] of widths){await command('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:t.deviceScaleFactor,mobile:width<500});for(const tab of ['chats','contacts','discover','me']){await root(tab);await noOverflow(width+' '+tab);await capture(width+'-'+tab);}
      await root('chats');metrics.push(await evaluate(`(()=>{const s=document.querySelector('.phone-shell'),h=document.querySelector('.topbar'),row=document.querySelector('.conversation'),a=row.querySelector('.avatar');return {viewport:${width},shellX:s.getBoundingClientRect().x,shellY:s.getBoundingClientRect().y,shellBottom:s.getBoundingClientRect().bottom,outline:getComputedStyle(s).outlineStyle,shellWidth:s.clientWidth,shellHeight:s.clientHeight,headerHeight:h.getBoundingClientRect().height,rowHeight:row.getBoundingClientRect().height,avatarWidth:a.getBoundingClientRect().width,avatarX:a.getBoundingClientRect().x-s.getBoundingClientRect().x};})()`));const m=metrics.at(-1);assert.equal(m.shellWidth,Math.min(width,430));assert.equal(m.shellHeight,width>=481?height-24:height);assert.equal(m.shellY,width>=481?12:0);assert.equal(m.shellBottom,width>=481?height-12:height);assert.equal(m.shellX,(width-m.shellWidth)/2);assert.ok(m.headerHeight>=44);assert.equal(m.rowHeight,72);assert.equal(m.avatarWidth,48);assert.equal(m.avatarX,16);
      await click('[data-open-chat]');assert.equal((await rect('.topbar')).height,44,'root spacing must not alter chat header');await noOverflow(width+' chat');await click('[data-action=toggle-emoji]');await wait('!!document.querySelector(".emoji-board")');await noOverflow(width+' emoji');const e=await rect('.chat-composer');assert.ok(e.height>=230&&e.height<m.shellHeight&&e.bottom<=height+1,JSON.stringify({width,e}));assert.equal(await evaluate('getComputedStyle(document.querySelector(".emoji-grid")).gridTemplateColumns.split(" ").length'),7);await capture(width+'-chat-emoji');await click('[data-action=toggle-emoji]');await click('[data-action=toggle-panel]');await noOverflow(width+' panel');await capture(width+'-chat-more');await click('[data-action=toggle-panel]');await click('[data-action=chat-details]');await noOverflow(width+' chat-info');await capture(width+'-chat-info');await root('discover');await buttonText('朋友圈');await noOverflow(width+' moments');await click('[data-action=compose-moment]');await capture(width+'-moment-compose');await noOverflow(width+' compose');await root('me');await buttonText('设置');await noOverflow(width+' settings');await capture(width+'-settings');
    }
  });
  await check('server data and login survive browser reload',async()=>{
    await root('chats');await command('Page.reload');await wait('!!document.querySelector(".bottom-tabs")');assert.ok(await evaluate('Pipi.getState().moments.some(x=>x.content==="HEADLESS_NATIVE_MOMENT"&&x.comments.some(c=>c.content==="HEADLESS_NATIVE_COMMENT"))'));assert.ok(await evaluate('Pipi.getState().messages.some(x=>x.content==="UI_SHORT_FAILURE"&&x.status==="error")'));
  });
